"""Curated Shu dossiers; Zhang Fei remains the approved independent reference."""
from dossier_support import set_dossier, record, career


def apply(people, events, R):
    def put(pid, *, offices, facts, **data):
        # Reuse the established dated life events, adding evidence for the office column.
        person = next(p for p in people if p['id'] == pid)
        assert len(offices) == len(person['milestones']), pid
        careers = []
        for m, (office, sources) in zip(person['milestones'], offices):
            old = [(r['blockId'], r['quote'], r['sourceBook']) if r.get('sourceBook') else (r['blockId'], r['quote']) for r in m['refs']]
            careers.append(career(m['when'], m['title'], m['text'], office, old + sources, m.get('eventIds', [])))
        set_dossier(people, R, pid, facts=facts, careers=careers, **data)

